INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2829', '43226', '437311', 'Aucune', '1', '1', 'Pensez-vous que L’établissement vous a fourni une solution TV/Audio/Internet complète ?', 'Do You Think The Establishment Has Provided You With A Complete TV/Audio/Internet Solution?', '¿Cree que el establecimiento le ha proporcionado una solución completa de TV/Audio/Internet?', 'Você acha que o estabelecimento lhe forneceu uma solução completa de TV/Áudio/Internet?', 'Pensi che l\'establishment ti abbia fornito una soluzione TV/audio/Internet completa?', 'Считаете ли вы, что заведение предоставило вам комплексное решение для телевидения, аудио и Интернета?', 'Glauben Sie, dass die Einrichtung Ihnen eine komplette TV-/Audio-/Internetlösung bereitgestellt hat?', '您认为该机构为您提供了完整的电视/音频/互联网解决方案吗？', 'هل تعتقد أن المؤسسة قد وفرت لك حلاً متكاملاً للتلفزيون/الصوت/الإنترنت؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2830', '43226', '437311', 'Aucune', '2', '1', 'L’utilisation de la TV et de ses fonctionnalités vous a-t-elle semblé facile ?', 'Did using the TV and its features seem easy to you?', '¿Te pareció fácil utilizar el televisor y sus funciones?', 'Usar a TV e seus recursos pareceu fácil para você?', 'Ti è sembrato facile utilizzare la TV e le sue funzionalità?', 'Вам показалось простым использование телевизора и его функций?', 'Fanden Sie die Bedienung des Fernsehers und seiner Funktionen einfach?', '您觉得使用电视及其功能是否容易？', 'هل يبدو لك استخدام التلفزيون ومميزاته سهلاً؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2831', '43226', '437311', 'Aucune', '3', '1', 'Avez-vous rencontré des problèmes avec la télécommande de votre TV ?', 'Have you experienced problems with your TV remote control?', '¿Has tenido problemas con el control remoto de tu televisor?', 'Você teve problemas com o controle remoto da TV?', 'Hai riscontrato problemi con il telecomando del televisore?', 'Были ли у вас проблемы с пультом дистанционного управления телевизором?', 'Haben Sie Probleme mit Ihrer TV-Fernbedienung gehabt?', '您是否遇到过电视遥控器问题？', 'هل واجهت مشاكل مع جهاز التحكم عن بعد الخاص بالتلفزيون؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2832', '43226', '437311', 'Aucune', '4', '1', 'Le personnel soignant a-t-il su répondre à vos besoins ?', 'Were the nursing staff able to meet your needs?', '¿El personal de enfermería pudo satisfacer sus necesidades?', 'A equipe de enfermagem conseguiu atender às suas necessidades?', 'Il personale infermieristico è stato in grado di soddisfare le tue esigenze?', 'Был ли медперсонал в состоянии удовлетворить ваши потребности?', 'Konnte das Pflegepersonal Ihren Bedürfnissen gerecht werden?', '护理人员能够满足您的需求吗？', 'هل طاقم التمريض قادر على تلبية احتياجاتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2833', '43226', '437311', 'Aucune', '5', '1', 'Le personnel soignant a-t-il été réactif face à vos problèmes et/ou vos demandes ?', 'Were the healthcare staff responsive to your problems and/or requests?', '¿El personal de atención médica respondió a sus problemas y/o solicitudes?', 'A equipe de saúde respondeu aos seus problemas e/ou solicitações?', 'Il personale sanitario ha risposto ai tuoi problemi e/o richieste?', 'Отреагировал ли медицинский персонал на ваши проблемы и/или просьбы?', 'Hat das Gesundheitspersonal auf Ihre Probleme und/oder Wünsche reagiert?', '医护人员是否对您的问题和/或要求做出了回应？', 'هل كان موظفو الرعاية الصحية مستجيبين لمشاكلك و/أو طلباتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2834', '43226', '437311', 'Aucune', '6', '1', 'Avez-vous rencontré des problèmes quant à la réception des chaînes de télévision ?', 'Have You Encountered Any Problems Receiving TV Channels?', '¿Ha tenido algún problema al recibir canales de televisión?', 'Você encontrou algum problema ao receber canais de TV?', 'Hai riscontrato problemi nella ricezione dei canali TV?', 'Сталкивались ли вы с проблемами при приеме телеканалов?', 'Sind beim Empfang von Fernsehsendern Probleme aufgetreten?', '您在接收电视频道时遇到过任何问题吗？', 'هل واجهت أي مشاكل في استقبال القنوات التلفزيونية؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2835', '43226', '437311', 'Aucune', '7', '1', 'Êtes-vous satisfait des différentes informations s’affichant sur votre écran ?', 'Are You Satisfied With The Different Information Displayed On Your Screen?', '¿Está satisfecho con la diferente información que se muestra en su pantalla?', 'Você está satisfeito com as diferentes informações exibidas na tela?', 'Sei soddisfatto delle diverse informazioni visualizzate sullo schermo?', 'Удовлетворены ли вы различной информацией, отображаемой на вашем экране?', 'Sind Sie mit den verschiedenen auf Ihrem Bildschirm angezeigten Informationen zufrieden?', '您对屏幕上显示的不同信息满意吗？', 'هل أنت راضٍ عن المعلومات المختلفة المعروضة على شاشتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2836', '43226', '437311', 'Aucune', '8', '1', 'Le service WIFI de l’établissement vous a-t-il contenté ?', 'Did the establishment’s WIFI service please you?', '¿Te gustó el servicio WIFI del establecimiento?', 'O serviço WIFI do estabelecimento lhe agradou?', 'Ti è piaciuto il servizio WIFI della struttura?', 'Порадовал ли вас WIFI в заведении?', 'Hat Ihnen der WLAN-Service des Hauses gefallen?', '酒店的 WIFI 服务令您满意吗？', 'هل نالت خدمة WIFI الخاصة بالمنشأة إعجابك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2837', '43226', '437311', 'Aucune', '9', '1', 'La propreté de la chambre vous a-t-elle semblé à la hauteur ?', 'Did the cleanliness of the room seem up to you?', '¿Te pareció que la limpieza de la habitación dependía de ti?', 'A limpeza do quarto lhe pareceu adequada?', 'La pulizia della camera ti è sembrata all\'altezza?', 'Вам понравилась чистота в номере?', 'Hat Ihnen die Sauberkeit des Zimmers gefallen?', '您认为房间的清洁度符合您的要求吗？', 'هل بدت نظافة الغرفة متروكة لك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2838', '43226', '437311', 'Aucune', '10', '1', 'La propreté de la salle de bains vous a-t elle semblé convenable ?', 'Did the cleanliness of the bathroom seem suitable to you?', '¿Te pareció adecuada la limpieza del baño?', 'A limpeza do banheiro lhe pareceu adequada?', 'La pulizia del bagno ti è sembrata adeguata?', 'Чистота ванной показалась вам подходящей?', 'Kam Ihnen die Sauberkeit des Badezimmers angemessen vor?', '浴室的清洁度是否适合您？', 'هل تبدو نظافة الحمام مناسبة لك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2839', '43226', '437311', 'Aucune', '11', '1', 'Le service a-t-Il été à la hauteur de vos espérances ?', 'Did the Service Live Up to Your Expectations?', '¿El servicio estuvo a la altura de sus expectativas?', 'O serviço correspondeu às suas expectativas?', 'Il servizio è stato all\'altezza delle tue aspettative?', 'Оправдал ли сервис ваши ожидания?', 'Hat der Service Ihren Erwartungen entsprochen?', '服务达到您的期望吗？', 'هل ترقى الخدمة إلى مستوى توقعاتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2840', '43226', '437311', 'Aucune', '12', '1', 'Est-ce que le personnel a su répondre à vos besoins et à vos demandes ?', 'Did the staff respond to your needs and requests?', '¿El personal respondió a sus necesidades y solicitudes?', 'A equipe respondeu às suas necessidades e solicitações?', 'Lo staff ha risposto alle tue esigenze e richieste?', 'Отреагировал ли персонал на ваши нужды и запросы?', 'Ist das Personal auf Ihre Bedürfnisse und Wünsche eingegangen?', '工作人员是否回应了您的需求和要求？', 'هل استجاب الموظفون لاحتياجاتك وطلباتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2841', '43226', '437311', 'Aucune', '13', '1', 'Avez-vous trouvé votre chambre confortable ?', 'Did you find your room comfortable?', '¿Encontró cómoda su habitación?', 'Você achou seu quarto confortável?', 'Hai trovato confortevole la tua stanza?', 'Вы нашли свою комнату удобной?', 'Fanden Sie Ihr Zimmer komfortabel?', '您觉得您的房间舒适吗？', 'هل وجدت غرفتك مريحة؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2842', '43226', '437311', 'Aucune', '14', '1', 'Selon vous, Le service lié à la TV est-il simple d’utilisation ?', 'In your opinion, is the TV-related service easy to use?', '¿En su opinión, el servicio relacionado con la televisión es fácil de utilizar?', 'Na sua opinião, o serviço relacionado à TV é fácil de usar?', 'Secondo te il servizio legato alla TV è facile da usare?', 'На ваш взгляд, прост ли в использовании сервис, связанный с телевидением?', 'Ist der TV-bezogene Dienst Ihrer Meinung nach einfach zu nutzen?', '您认为电视相关服务好用吗？', 'في رأيك، هل الخدمة المتعلقة بالتلفزيون سهلة الاستخدام؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2843', '43226', '437311', 'Aucune', '15', '1', 'Êtes-vous satisfait de votre séjour en général ?', 'Are you satisfied with your stay in general?', '¿Está satisfecho con su estancia en general?', 'Você está satisfeito com sua estadia em geral?', 'Sei soddisfatto del tuo soggiorno in generale?', 'Довольны ли вы своим пребыванием в целом?', 'Sind Sie mit Ihrem Aufenthalt im Allgemeinen zufrieden?', '您对您的住宿总体满意吗？', 'هل أنت راضي عن إقامتك بشكل عام؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2844', '43226', '437311', 'Aucune', '16', '1', 'Avez-vous été dérangé pendant votre séjour ?', 'Were you disturbed during your stay?', '¿Le molestaron durante su estancia?', 'Você foi incomodado durante sua estadia?', 'Sei stato disturbato durante il tuo soggiorno?', 'Вас беспокоили во время вашего пребывания?', 'Wurden Sie während Ihres Aufenthaltes gestört?', '您在住宿期间有受到打扰吗？', 'هل شعرت بالانزعاج أثناء إقامتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2845', '43226', '437311', 'Aucune', '17', '1', 'Le service lié aux repas vous a-t-il semblé réactif ?', 'Did the meal-related service seem responsive to you?', '¿El servicio relacionado con las comidas le pareció receptivo?', 'O serviço relacionado às refeições pareceu receptivo para você?', 'Il servizio legato ai pasti ti è sembrato rispondente?', 'Служба, связанная с питанием, показалась вам отзывчивой?', 'Scheint Ihnen der Essensservice entgegenkommend zu sein?', '与餐饮相关的服务对您来说是否有回应？', 'هل بدت الخدمة المتعلقة بالوجبات مستجيبة لك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2846', '43226', '437311', 'Aucune', '18', '1', 'Avez-vous été satisfait de vos repas ?', 'Were you satisfied with your meals?', '¿Quedó satisfecho con sus comidas?', 'Você ficou satisfeito com suas refeições?', 'Eri soddisfatto dei tuoi pasti?', 'Вы были довольны едой?', 'Waren Sie mit Ihren Mahlzeiten zufrieden?', '您对您的饭菜满意吗？', 'هل كنت راضياً عن وجباتك؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2847', '43226', '437311', 'Aucune', '19', '1', 'Le room service a-t-il été agréable ?', 'Was the room service pleasant?', '¿Fue agradable el servicio de habitaciones?', 'O serviço de quarto foi agradável?', 'Il servizio in camera è stato piacevole?', 'Обслуживание номеров понравилось?', 'War der Zimmerservice angenehm?', '客房服务令人愉快吗？', 'هل كانت خدمة الغرف ممتعة؟');
INSERT INTO `questionnaire` (`id`, `etablissement_id`, `service_id`, `question`, `position`, `active`, `fr`, `en`, `es`, `pt`, `it`, `ru`, `de`, `zh`, `ar`) VALUES ('2848', '43226', '437311', 'Aucune', '20', '1', 'En général, avez-vous du attendre un long laps de temps avant que les différents services répondent à vos demandes ?', 'In general, did you have to wait a long time before the different services responded to your requests?', 'En general, ¿tuviste que esperar mucho tiempo antes de que los diferentes servicios respondieran a tus solicitudes?', 'Em geral, teve de esperar muito tempo até que os diferentes serviços respondessem aos seus pedidos?', 'In generale, hai dovuto aspettare molto tempo prima che i diversi servizi rispondessero alle tue richieste?', 'В общем, вам пришлось долго ждать, пока разные сервисы отреагируют на ваши запросы?', 'Mussten Sie im Allgemeinen lange warten, bis die verschiedenen Dienste auf Ihre Anfragen reagierten?', '一般来说，您是否需要等待很长时间才能得到不同的服务响应您的请求？', 'بشكل عام، هل اضطررت للانتظار طويلاً قبل أن تستجيب الخدمات المختلفة لطلباتك؟');
